//go:build baselinecheck

package mqtt
import("context";"encoding/binary";"fmt";"net";"sync/atomic";"testing";"time")
func TestBaseline(t *testing.T){a,b:=net.Pipe();defer a.Close();defer b.Close();c:=&BaseClient{Transport:b};ids:=make(chan uint16,2);allowAck:=make(chan struct{});brokerDone:=make(chan struct{});go func(){defer close(brokerDone);kind,_,_,e:=readPacket(a);if e!=nil||kind!=packetConnect{return};a.Write([]byte{0x20,2,0,0});for i:=0;i<2;i++{kind,_,body,e:=readPacket(a);if e!=nil||kind!=packetSubscribe{return};ids<-binary.BigEndian.Uint16(body[:2])};<-allowAck;a.Write([]byte{0x90,3,0,1,0})}();ctx,cancel:=context.WithTimeout(context.Background(),2*time.Second);defer cancel();if _,e:=c.Connect(ctx,"capture");e!=nil{t.Fatal(e)};atomic.StoreUint32(&c.idLast,0);first:=make(chan error,1);second:=make(chan error,1);go func(){_,e:=c.Subscribe(ctx,Subscription{Topic:"a",QoS:QoS0});first<-e}();var id1 uint16;select{case id1=<-ids:case <-ctx.Done():t.Fatal(ctx.Err())};atomic.StoreUint32(&c.idLast,65535);go func(){_,e:=c.Subscribe(ctx,Subscription{Topic:"b",QoS:QoS0});second<-e}();var id2 uint16;select{case id2=<-ids:case <-ctx.Done():t.Fatal(ctx.Err())};close(allowAck);select{case e:=<-second:if e!=nil{t.Fatal(e)};case <-ctx.Done():t.Fatal(ctx.Err())};select{case e:=<-first:t.Fatalf("first unexpectedly completed: %v",e);default:};fmt.Printf("connected=true wire_id_first=%d wire_id_second=%d first_pending=true second_completed=true\n",id1,id2);if id1!=1||id2!=1{t.Fatal("old collision did not reproduce")};c.Close();select{case <-first:case <-ctx.Done():t.Fatal("first did not stop")};<-brokerDone}
